<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import Breadcrumbs from '../../../components/admin/Breadcrumbs.vue';
import PageHeader from '../../../components/admin/PageHeader.vue';
import StatusBadge from '../../../components/admin/StatusBadge.vue';
import FieldError from '../../../components/FieldError.vue';
import StatusNotice from '../../../components/StatusNotice.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface Supplier { id: string; name: string; code: string; contact_name: string | null; email: string | null; phone: string | null; website: string | null; notes: string | null; status: string }
interface Variant { id: string; product_name: string; name: string | null; sku: string }
interface SupplierProduct { id: string; product_variant_id: string; product_name: string; variant_name: string | null; sku: string; supplier_sku: string | null; unit_cost: string; currency: string; minimum_order_quantity: number; order_multiple: number | null; lead_time_days: number | null; is_preferred: boolean; notes: string | null; status: string }

const props = defineProps<{ supplier: Supplier; products: SupplierProduct[]; variants: Variant[]; statuses: string[] }>();
const { t, te } = useI18n();
const page = usePage<PageProps>();
const permissions = computed(() => page.props.currentTenantMembership?.permissions ?? []);
const canUpdate = computed(() => permissions.value.includes('suppliers.update') && props.supplier.status !== 'ARCHIVED');
const canArchive = computed(() => permissions.value.includes('suppliers.archive') && props.supplier.status !== 'ARCHIVED');
const notice = computed(() => page.props.status ? t('procurement.notices.completed') : undefined);
const supplierForm = useForm({ name: props.supplier.name, code: props.supplier.code, contact_name: props.supplier.contact_name ?? '', email: props.supplier.email ?? '', phone: props.supplier.phone ?? '', website: props.supplier.website ?? '', notes: props.supplier.notes ?? '', status: props.supplier.status });
const productForm = useForm({ product_variant_id: '', supplier_sku: '', unit_cost: '', currency: page.props.currentStore?.currency ?? '', minimum_order_quantity: 1, order_multiple: null as number | null, lead_time_days: null as number | null, is_preferred: false, notes: '' });
const productForms = props.products.map((product) => ({ id: product.id, form: useForm({ supplier_sku: product.supplier_sku ?? '', unit_cost: product.unit_cost, currency: product.currency, minimum_order_quantity: product.minimum_order_quantity, order_multiple: product.order_multiple, lead_time_days: product.lead_time_days, is_preferred: product.is_preferred, notes: product.notes ?? '', status: product.status }) }));
const localizedError = (message?: string) => message?.includes('code has already') ? t('procurement.errors.codeTaken') : message;
const saveSupplier = () => { if (!supplierForm.processing && canUpdate.value) supplierForm.patch(`/admin/suppliers/${props.supplier.id}`, { preserveScroll: true }); };
const addProduct = () => { if (!productForm.processing) productForm.post(`/admin/suppliers/${props.supplier.id}/products`, { preserveScroll: true }); };
const saveProduct = (entry: (typeof productForms)[number]) => { if (!entry.form.processing) entry.form.patch(`/admin/supplier-products/${entry.id}`, { preserveScroll: true }); };
const archiveProduct = (product: SupplierProduct) => { if (window.confirm(t('procurement.suppliers.archiveProductConfirm', { sku: product.sku }))) router.post(`/admin/supplier-products/${product.id}/archive`, {}, { preserveScroll: true }); };
const archiveSupplier = () => { if (window.confirm(t('procurement.suppliers.archiveConfirm', { name: props.supplier.name }))) router.post(`/admin/suppliers/${props.supplier.id}/archive`); };
</script>

<template>
    <Head :title="supplier.name" />
    <AdminLayout><section class="mx-auto grid w-full max-w-[90rem] gap-5 sm:gap-6">
        <Breadcrumbs :items="[{ label: t('nav.procurement') }, { label: t('procurement.suppliers.title'), href: '/admin/suppliers' }, { label: supplier.name }]" />
        <PageHeader :title="supplier.name" :eyebrow="t('common.allCompany')" :description="t('procurement.suppliers.editDescription')"><template #actions><div class="grid grid-cols-2 gap-2 sm:flex"><button v-if="canArchive" type="button" class="min-h-10 rounded-md border border-admin-danger-border bg-admin-danger-bg px-4 text-sm font-semibold text-admin-danger" @click="archiveSupplier">{{ t('procurement.suppliers.archive') }}</button><Link href="/admin/suppliers" class="inline-flex min-h-10 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold">{{ t('procurement.backSuppliers') }}</Link></div></template></PageHeader>
        <StatusNotice :message="notice" />
        <aside v-if="supplier.status === 'ARCHIVED' || !canUpdate" class="rounded-md border border-admin-warning-border bg-admin-warning-bg px-4 py-3"><p class="text-sm font-semibold">{{ supplier.status === 'ARCHIVED' ? t('procurement.suppliers.archivedTitle') : t('procurement.readOnlyTitle') }}</p><p class="mt-0.5 text-xs text-admin-text-secondary">{{ supplier.status === 'ARCHIVED' ? t('procurement.suppliers.archivedHelp') : t('procurement.readOnlyHelp') }}</p></aside>

        <form class="admin-card overflow-hidden" @submit.prevent="saveSupplier"><header class="flex items-center justify-between gap-3 border-b border-admin-border px-5 py-4 sm:px-6"><div><p class="admin-label text-admin-secondary">{{ t('procurement.suppliers.section') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('procurement.suppliers.details') }}</h2></div><StatusBadge :status="supplier.status" /></header><div class="grid gap-5 p-5 sm:p-6 md:grid-cols-2">
            <div><label for="edit-supplier-name" class="mb-1.5 block text-sm font-semibold">{{ t('procurement.name') }} *</label><input id="edit-supplier-name" v-model="supplierForm.name" :disabled="!canUpdate" required maxlength="160" class="admin-control w-full px-3 text-sm disabled:bg-admin-canvas" /><FieldError :message="supplierForm.errors.name" /></div>
            <div><label for="edit-supplier-code" class="mb-1.5 block text-sm font-semibold">{{ t('procurement.code') }} *</label><input id="edit-supplier-code" v-model="supplierForm.code" :disabled="!canUpdate" required maxlength="40" class="admin-control w-full px-3 font-mono text-sm uppercase disabled:bg-admin-canvas" /><FieldError :message="localizedError(supplierForm.errors.code)" /></div>
            <div><label for="edit-supplier-contact" class="mb-1.5 block text-sm font-semibold">{{ t('procurement.contactName') }}</label><input id="edit-supplier-contact" v-model="supplierForm.contact_name" :disabled="!canUpdate" maxlength="160" class="admin-control w-full px-3 text-sm disabled:bg-admin-canvas" /><FieldError :message="supplierForm.errors.contact_name" /></div>
            <div><label for="edit-supplier-email" class="mb-1.5 block text-sm font-semibold">{{ t('procurement.email') }}</label><input id="edit-supplier-email" v-model="supplierForm.email" :disabled="!canUpdate" type="email" maxlength="254" class="admin-control w-full px-3 text-sm disabled:bg-admin-canvas" /><FieldError :message="supplierForm.errors.email" /></div>
            <div><label for="edit-supplier-phone" class="mb-1.5 block text-sm font-semibold">{{ t('procurement.phone') }}</label><input id="edit-supplier-phone" v-model="supplierForm.phone" :disabled="!canUpdate" maxlength="40" class="admin-control w-full px-3 text-sm disabled:bg-admin-canvas" /><FieldError :message="supplierForm.errors.phone" /></div>
            <div><label for="edit-supplier-website" class="mb-1.5 block text-sm font-semibold">{{ t('procurement.website') }}</label><input id="edit-supplier-website" v-model="supplierForm.website" :disabled="!canUpdate" type="url" maxlength="2048" class="admin-control w-full px-3 text-sm disabled:bg-admin-canvas" /><FieldError :message="supplierForm.errors.website" /></div>
            <div><label for="edit-supplier-status" class="mb-1.5 block text-sm font-semibold">{{ t('common.status') }}</label><select id="edit-supplier-status" v-model="supplierForm.status" :disabled="!canUpdate" class="admin-control w-full px-3 text-sm disabled:bg-admin-canvas"><option v-for="value in statuses" :key="value" :value="value">{{ te(`status.${value}`) ? t(`status.${value}`) : value }}</option></select><FieldError :message="supplierForm.errors.status" /></div>
            <div class="md:col-span-2"><label for="edit-supplier-notes" class="mb-1.5 block text-sm font-semibold">{{ t('procurement.notes') }}</label><textarea id="edit-supplier-notes" v-model="supplierForm.notes" :disabled="!canUpdate" rows="4" maxlength="10000" class="admin-control w-full px-3 py-2 text-sm disabled:bg-admin-canvas" /><FieldError :message="supplierForm.errors.notes" /></div>
        </div><footer v-if="canUpdate" class="flex justify-end border-t border-admin-border bg-admin-canvas px-5 py-4 sm:px-6"><button :disabled="supplierForm.processing" class="min-h-10 rounded-md bg-admin-primary px-5 text-sm font-semibold text-white disabled:opacity-50">{{ supplierForm.processing ? t('common.saving') : t('common.saveChanges') }}</button></footer></form>

        <section><div class="mb-3"><p class="admin-label text-admin-secondary">{{ t('procurement.suppliers.catalogSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('procurement.suppliers.products') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('procurement.suppliers.productsHelp') }}</p></div>
            <div class="grid gap-3"><form v-for="(entry, index) in productForms" :key="entry.id" class="admin-card overflow-hidden" @submit.prevent="saveProduct(entry)"><header class="flex flex-wrap items-start justify-between gap-3 border-b border-admin-border bg-admin-canvas px-4 py-3"><div class="min-w-0"><h3 class="break-words text-sm font-semibold">{{ products[index].product_name }}</h3><p class="mt-0.5 break-words font-mono text-[11px] text-admin-neutral">{{ products[index].variant_name ?? t('procurement.defaultVariant') }} · {{ products[index].sku }}</p></div><div class="flex items-center gap-2"><span v-if="products[index].is_preferred" class="rounded border border-admin-info-border bg-admin-info-bg px-1.5 py-0.5 text-[10px] font-semibold text-admin-info">{{ t('procurement.preferred') }}</span><StatusBadge :status="products[index].status" /></div></header><div class="grid gap-4 p-4 sm:grid-cols-2 lg:grid-cols-4">
                <label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.supplierSku') }}<input v-model="entry.form.supplier_sku" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" maxlength="100" class="admin-control w-full px-3 font-mono text-sm font-normal disabled:bg-admin-canvas" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.unitCost') }}<input v-model="entry.form.unit_cost" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" required inputmode="decimal" pattern="\d{1,15}(\.\d{1,4})?" class="admin-control w-full px-3 font-mono text-sm font-normal disabled:bg-admin-canvas" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.currency') }}<input v-model="entry.form.currency" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" required maxlength="3" pattern="[A-Za-z]{3}" class="admin-control w-full px-3 font-mono text-sm font-normal uppercase disabled:bg-admin-canvas" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('common.status') }}<select v-model="entry.form.status" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" class="admin-control w-full px-3 text-sm font-normal disabled:bg-admin-canvas"><option value="ACTIVE">{{ t('status.ACTIVE') }}</option><option value="INACTIVE">{{ t('status.INACTIVE') }}</option><option v-if="products[index].status === 'ARCHIVED'" value="ARCHIVED">{{ t('status.ARCHIVED') }}</option></select></label>
                <label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.minimumOrder') }}<input v-model.number="entry.form.minimum_order_quantity" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" required type="number" min="1" class="admin-control w-full px-3 font-mono text-sm font-normal disabled:bg-admin-canvas" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.orderMultiple') }}<input v-model.number="entry.form.order_multiple" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" type="number" min="1" class="admin-control w-full px-3 font-mono text-sm font-normal disabled:bg-admin-canvas" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.leadTime') }}<input v-model.number="entry.form.lead_time_days" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" type="number" min="0" max="3650" class="admin-control w-full px-3 font-mono text-sm font-normal disabled:bg-admin-canvas" /></label><label class="flex min-h-9 items-center gap-2 self-end text-xs font-semibold"><input v-model="entry.form.is_preferred" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" type="checkbox" class="size-4" />{{ t('procurement.preferred') }}</label>
                <label class="grid gap-1.5 text-xs font-semibold sm:col-span-2 lg:col-span-4">{{ t('procurement.notes') }}<textarea v-model="entry.form.notes" :disabled="!canUpdate || products[index].status === 'ARCHIVED'" rows="2" maxlength="10000" class="admin-control w-full px-3 py-2 text-sm font-normal disabled:bg-admin-canvas" /></label><FieldError class="sm:col-span-2 lg:col-span-4" :message="entry.form.errors.unit_cost ?? entry.form.errors.currency ?? entry.form.errors.minimum_order_quantity ?? entry.form.errors.order_multiple ?? entry.form.errors.lead_time_days ?? entry.form.errors.notes" />
            </div><footer v-if="canUpdate && products[index].status !== 'ARCHIVED'" class="flex flex-col-reverse gap-2 border-t border-admin-border bg-admin-canvas px-4 py-3 sm:flex-row sm:justify-end"><button v-if="canArchive" type="button" class="min-h-9 rounded-md px-3 text-xs font-semibold text-admin-danger" @click="archiveProduct(products[index])">{{ t('procurement.archiveMapping') }}</button><button :disabled="entry.form.processing" class="min-h-9 rounded-md bg-admin-primary px-4 text-xs font-semibold text-white disabled:opacity-50">{{ entry.form.processing ? t('common.saving') : t('common.save') }}</button></footer></form></div>
        </section>

        <form v-if="canUpdate" class="admin-card overflow-hidden" @submit.prevent="addProduct"><header class="border-b border-admin-border px-5 py-4"><p class="admin-label text-admin-secondary">{{ t('procurement.suppliers.addSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('procurement.suppliers.addProduct') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('procurement.suppliers.addProductHelp') }}</p></header><div class="grid gap-4 p-5 sm:grid-cols-2 lg:grid-cols-3">
            <label class="grid gap-1.5 text-xs font-semibold sm:col-span-2">{{ t('procurement.productVariant') }} *<select v-model="productForm.product_variant_id" required class="admin-control w-full px-3 text-sm font-normal"><option value="" disabled>{{ t('procurement.selectVariant') }}</option><option v-for="variant in variants" :key="variant.id" :value="variant.id">{{ variant.product_name }} · {{ variant.sku }}<template v-if="variant.name"> · {{ variant.name }}</template></option></select></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.supplierSku') }}<input v-model="productForm.supplier_sku" maxlength="100" class="admin-control px-3 font-mono text-sm font-normal" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.unitCost') }} *<input v-model="productForm.unit_cost" required inputmode="decimal" pattern="\d{1,15}(\.\d{1,4})?" class="admin-control px-3 font-mono text-sm font-normal" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.currency') }} *<input v-model="productForm.currency" required maxlength="3" pattern="[A-Za-z]{3}" class="admin-control px-3 font-mono text-sm font-normal uppercase" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.minimumOrder') }} *<input v-model.number="productForm.minimum_order_quantity" required type="number" min="1" class="admin-control px-3 font-mono text-sm font-normal" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.orderMultiple') }}<input v-model.number="productForm.order_multiple" type="number" min="1" class="admin-control px-3 font-mono text-sm font-normal" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.leadTime') }}<input v-model.number="productForm.lead_time_days" type="number" min="0" max="3650" class="admin-control px-3 font-mono text-sm font-normal" /></label><label class="flex min-h-9 items-center gap-2 self-end text-xs font-semibold"><input v-model="productForm.is_preferred" type="checkbox" class="size-4" />{{ t('procurement.preferred') }}</label><label class="grid gap-1.5 text-xs font-semibold sm:col-span-2 lg:col-span-3">{{ t('procurement.notes') }}<textarea v-model="productForm.notes" rows="2" maxlength="10000" class="admin-control px-3 py-2 text-sm font-normal" /></label><FieldError class="sm:col-span-2 lg:col-span-3" :message="productForm.errors.product_variant_id ?? productForm.errors.unit_cost ?? productForm.errors.currency ?? productForm.errors.minimum_order_quantity ?? productForm.errors.order_multiple ?? productForm.errors.lead_time_days ?? productForm.errors.notes" />
        </div><footer class="flex justify-end border-t border-admin-border bg-admin-canvas px-5 py-4"><button :disabled="productForm.processing || !variants.length" class="min-h-10 rounded-md bg-admin-primary px-5 text-sm font-semibold text-white disabled:opacity-50">{{ productForm.processing ? t('procurement.adding') : t('procurement.suppliers.addProduct') }}</button></footer></form>
    </section></AdminLayout>
</template>
